INSERT INTO lessons (level_id,lesson_key,sort_order,title,title_translation,description,primary_outcome_key,estimated_duration_sec,source_hash,status,metadata)
VALUES (@level_id,'EN-A1-L-0101',101,'A different case','یک مورد متفاوت','با case درباره یک مورد یا وضعیت مشخص حرف بزن.','EN-A1-OUTCOME-0101',420,'5f3e9c65a025283c52cbdee1dbf0a925a335e501ecd378c2cdada801e8050e31','validated','{"outcomeFa":"case را به معنی یک مورد یا وضعیت مشخص در دو جمله کوتاه به کار ببری.","scenarioFa":"روبی و سارا در سالن محله دو درخواست متفاوت را روی برگه ثبت‌نام بررسی می‌کنند.","prerequisiteOutcomeKeys":["EN-A1-OUTCOME-0100"],"curriculum":{"startingKnowledge":"early_a1_spoken_core_and_recent_review","targetConstructions":[{"key":"EN-CONSTR-0101-CASE","form":"This is a special case","meaningFa":"اشاره به یک مورد یا وضعیت مشخص"}],"supportLanguage":[{"form":"Is this request unusual?","meaningFa":"این درخواست غیرعادی است؟"},{"form":"And the other request?","meaningFa":"و درخواست دیگر؟"}],"assessmentBoundary":"Only the bounded A1 target sense of case used in this Lesson is assessed.","transferPlan":{"mode":"same_lesson","intent":"Recombine the same target sense in a second controlled conversational context."},"story":{"arcKey":"EN-A1-WALKING-GROUP","sceneKey":"EN-A1-FACTORY-SCENE-0101","learnerRoleKey":"sara","participants":["ruby","sara"],"introducedCharacterKeys":[],"relationshipState":"already_known","dependsOnLessonKeys":["EN-A1-L-0096"],"continuesLessonKey":"EN-A1-L-0096","settingFa":"سالن محله، کنار میز ثبت‌نام","storyBeatFa":"روبی درباره دو درخواست می‌پرسد و سارا با case آن‌ها را از هم جدا می‌کند."},"reviewLinks":[{"lessonKey":"EN-A1-L-0096","activityKeys":["A02"],"learningDemand":"retrieval","note":"Returning arc is spaced by 5 Lessons and the learner role/story beat is varied."}],"languageReference":{"specKey":"en-fa-A1-LESSON-SPEC-0101","specHash":"f0ba041715551f0c7519c50905886ac98bc0da96fe928e56fb868b19e938f0ad","grammarTargetKeys":[],"reviewLexicalLemmas":[],"usageFallbacks":[{"query":"a special case","rationale":"Exact bounded learner target collocation around the target word."},{"query":"a different case","rationale":"Exact changed-context target collocation around the target word."}],"noNewGrammarReason":"Lexical-focus Lesson using familiar A1 sentence patterns; no new grammar is claimed."},"pedagogyVersion":2},"pilot":false,"audioRequired":true,"humanEnglishAuditRequired":true,"dialogueRuntime":"guided_exchange","qualityStage":"model_reviewed_for_testing"}')
ON DUPLICATE KEY UPDATE level_id=VALUES(level_id),sort_order=VALUES(sort_order),title=VALUES(title),title_translation=VALUES(title_translation),description=VALUES(description),primary_outcome_key=VALUES(primary_outcome_key),estimated_duration_sec=VALUES(estimated_duration_sec),source_hash=VALUES(source_hash),status=VALUES(status),metadata=VALUES(metadata);
